fn test_a_raster_is_a_photograph_a_code_a_screenshot_a_logo_or_line_art_by_its_bits_and_its_shape() {
    let fi: &mut crate::port::Cells = &mut crate::port::Cells::new();
    ft_fi(fi, 1, 7, 2, 3, 8, 300, 0);
    crate::testport::assert_eq(fc_image_kind(fi, 0, 20000, 15000, 20000, 35000, 79200, 0) / 1024, fg_photo(), "a JPEG that needed three bits a pixel");
    crate::testport::assert_that((fc_image_kind(fi, 0, 20000, 15000, 20000, 35000, 79200, 0) % 1024) >= 600, "a sure one");
    ft_fi(fi, 1, 0, 2, 3, 8, 60, 0);
    crate::testport::assert_eq(fc_image_kind(fi, 0, 30000, 20000, 20000, 40000, 79200, 0) / 1024, fg_screenshot(), "a large flat one");
    crate::testport::assert_that((fc_image_kind(fi, 0, 30000, 20000, 20000, 40000, 79200, 0) % 1024) < 500, "which is not sure enough for a figure with no caption");
    crate::testport::assert_eq(fc_image_kind(fi, 0, 4000, 4000, 5000, 9000, 79200, 0) / 1024, fg_logo(), "a small flat one at the head of the page");
    crate::testport::assert_eq(fc_image_kind(fi, 0, 4000, 4000, 30000, 34000, 79200, 0) / 1024, fg_unknown(), "and in the middle of it");
    ft_fi(fi, 1, 9, 1, 1, 1, 20, 0);
    crate::testport::assert_eq(fc_image_kind(fi, 0, 20000, 5000, 20000, 25000, 79200, 0) / 1024, fg_barcode(), "a two-colour one far wider than high");
    crate::testport::assert_eq(fc_image_kind(fi, 0, 8000, 8000, 20000, 28000, 79200, 0) / 1024, fg_qr(), "a square two-colour one");
    crate::testport::assert_eq(fc_image_kind(fi, 0, 12000, 8000, 20000, 28000, 79200, 0) / 1024, fg_illustration(), "any other two-colour one is line art");
    crate::testport::assert_eq(fc_image_kind(fi, 5, 12000, 8000, 20000, 28000, 79200, 0) / 1024, fg_unknown(), "a placement with no row says nothing");
}
